<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { withBase } from 'vitepress'
interface User { id: string; username: string; email: string; displayName: string; role: 'member'|'moderator'; status: 'active'|'suspended'; createdAt: string; lastLoginAt: string; commentCount: number; postCount: number; replyCount: number }
interface Moderation { id: string; type: 'comment'|'post'|'reply'; content: string; status: string; createdAt: string; context: string; author: string }
interface Stats { users: number; activeUsers: number; suspendedUsers: number; comments: number; posts: number; replies: number; hiddenContent: number }
const state = ref<'loading'|'login'|'ready'|'unavailable'>('loading'); const username = ref('admin'); const password = ref(''); const search = ref(''); const users = ref<User[]>([]); const moderation = ref<Moderation[]>([]); const stats = ref<Stats | null>(null); const error = ref(''); const message = ref(''); const busy = ref('')
const typeName = { comment: '文章评论', post: '论坛帖子', reply: '论坛回复' }
const statName: Record<string, string> = { users:'用户', activeUsers:'正常用户', suspendedUsers:'停用用户', comments:'评论', posts:'帖子', replies:'回复', hiddenContent:'隐藏内容' }
const readError = async (response: Response) => { try { return (await response.json()).error || `请求失败（${response.status}）` } catch { return `请求失败（${response.status}）` } }
const load = async () => { state.value = 'loading'; error.value = ''; try { const [userResponse, moderationResponse, statsResponse] = await Promise.all([fetch(`/api/admin/users?search=${encodeURIComponent(search.value)}`, { credentials: 'same-origin' }), fetch('/api/admin/moderation?limit=100', { credentials: 'same-origin' }), fetch('/api/admin/community/stats', { credentials: 'same-origin' })]); if ([userResponse, moderationResponse, statsResponse].some(item => item.status === 401)) { state.value = 'login'; return }; if (!userResponse.ok || !moderationResponse.ok || !statsResponse.ok) { state.value = 'unavailable'; return }; users.value = await userResponse.json(); moderation.value = await moderationResponse.json(); stats.value = await statsResponse.json(); state.value = 'ready' } catch { state.value = 'unavailable' } }
onMounted(load)
const login = async () => { busy.value = 'login'; error.value = ''; const response = await fetch('/api/admin/login', { method: 'POST', credentials: 'same-origin', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ username: username.value, password: password.value }) }).catch(() => null); password.value = ''; if (!response?.ok) error.value = response ? await readError(response) : '无法连接管理服务。'; else await load(); busy.value = '' }
const saveUser = async (user: User) => { busy.value = user.id; error.value = ''; const response = await fetch(`/api/admin/users/${user.id}`, { method: 'PATCH', credentials: 'same-origin', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ role: user.role, status: user.status }) }); if (!response.ok) error.value = await readError(response); else { message.value = `用户 @${user.username} 已更新。`; await load() }; busy.value = '' }
const deleteUser = async (user: User) => { if (!confirm(`确认永久删除用户 @${user.username}？其历史内容将显示为已注销用户。`)) return; const response = await fetch(`/api/admin/users/${user.id}`, { method: 'DELETE', credentials: 'same-origin' }); if (!response.ok) error.value = await readError(response); else { message.value = '用户已删除。'; await load() } }
const moderate = async (item: Moderation, status: string) => { busy.value = item.id; const response = await fetch(`/api/admin/moderation/${item.type}/${item.id}`, { method: 'PATCH', credentials: 'same-origin', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ status }) }); if (!response.ok) error.value = await readError(response); else await load(); busy.value = '' }
</script>
<template><section class="case-admin"><div v-if="state === 'loading'" class="case-admin-state">正在读取用户与内容数据…</div><form v-else-if="state === 'login'" class="case-admin-login" @submit.prevent="login"><span>USER ADMIN</span><h1>用户与社区管理</h1><p>使用站点管理员账号登录。</p><label>账号<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><button :disabled="busy === 'login'">登录管理后台</button><p v-if="error" class="case-admin-feedback case-admin-feedback--error">{{ error }}</p></form><div v-else-if="state === 'unavailable'" class="case-admin-state"><h1>管理服务未连接</h1><p>请运行 <code>npm run admin</code> 后重试。</p></div><template v-else><header class="case-admin__hero"><div><span>COMMUNITY OPERATIONS</span><h1>用户与社区管理</h1><p>管理注册用户、权限状态、文章评论与论坛内容。</p></div><div class="site-admin__links"><a :href="withBase('/forum')" target="_blank">查看论坛 ↗</a><a :href="withBase('/admin/knowledge')">知识与 AI →</a></div></header><div v-if="stats" class="community-stats"><article v-for="(value, key) in stats" :key="key"><strong>{{ value }}</strong><span>{{ statName[key] }}</span></article></div><p v-if="error" class="case-admin-feedback case-admin-feedback--error">{{ error }}</p><p v-if="message" class="case-admin-feedback">{{ message }}</p><section class="user-admin-section"><header><div><h2>注册用户</h2><p>停用账号会立即注销其全部会话。</p></div><form class="forum-search" @submit.prevent="load"><input v-model="search" placeholder="用户名、显示名或邮箱"><button>搜索</button></form></header><div class="user-table-wrap"><table><thead><tr><th>用户</th><th>角色</th><th>状态</th><th>内容</th><th>操作</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><strong>{{ user.displayName }}</strong><small>@{{ user.username }}<br>{{ user.email }}</small></td><td><select v-model="user.role"><option value="member">用户</option><option value="moderator">版主</option></select></td><td><select v-model="user.status"><option value="active">正常</option><option value="suspended">停用</option></select></td><td>{{ user.commentCount }} 评 / {{ user.postCount }} 帖 / {{ user.replyCount }} 回</td><td><button @click="saveUser(user)" :disabled="busy === user.id">保存</button><button class="danger" @click="deleteUser(user)">删除</button></td></tr></tbody></table><div v-if="!users.length" class="community-empty">没有匹配用户。</div></div></section><section class="user-admin-section"><header><div><h2>内容审核</h2><p>按时间倒序显示最新 100 条社区内容。</p></div></header><div class="moderation-list"><article v-for="item in moderation" :key="`${item.type}-${item.id}`"><header><strong>{{ typeName[item.type] }} · {{ item.author }}</strong><span>{{ item.status }} · {{ item.createdAt.slice(0,16).replace('T',' ') }}</span></header><p>{{ item.content }}</p><footer><button @click="moderate(item, 'active')">恢复</button><button @click="moderate(item, 'hidden')">隐藏</button><button v-if="item.type === 'post'" @click="moderate(item, 'locked')">锁定</button><button class="danger" @click="moderate(item, 'deleted')">删除</button></footer></article><div v-if="!moderation.length" class="community-empty">暂无社区内容。</div></div></section></template></section></template>
